"""Useful search entry points and sharing paths, using existing lead destinations."""
import html
import shutil
from editorial import write_editorial_page

PAGES = [
('/home-tips/', 'Home Maintenance Tips & Checklists for Delco Homeowners', 'Practical home tips, a printable seasonal checklist and planning tools for Delco, Chester County and Main Line homeowners.', 'SMALL HABITS. FEWER SURPRISES.', 'A little care for the place you call home.', '''<p>Start with one useful job, not an overwhelming weekend list. These tips help you notice changes, collect the right details and choose the next conversation.</p><div class="growth-grid"><article><h2>Make a home reference folder.</h2><p>Keep equipment model numbers, installation dates, manuals, invoices and warranty terms together. A photo of the equipment label can make a service conversation easier.</p><a href="/project-kit/">Prepare a project sheet →</a></article><article><h2>Look before the season changes.</h2><p>Notice where drafts, moisture marks and comfort changes appear. Record the room and date. A repeated pattern is more useful than a guess about the cause.</p><a href="/seasonal-home-checklist/">Use the seasonal checklist →</a></article><article><h2>Compare the whole job.</h2><p>Two prices may cover different work. Ask what is included, excluded, who handles permits, and how changes are approved.</p><a href="/compare/">Compare two written estimates →</a></article><article><h2>Give the next person a head start.</h2><p>Write down what changed, when it started and any previous findings. Share that brief with the business you choose.</p><a href="/start/">Start a project request →</a></article></div><h2>Three details worth checking this month.</h2><ul><li>Read the filter instructions for your heating system and note the specified type and replacement schedule.</li><li>Check smoke and carbon monoxide alarm test and replacement instructions from the manufacturer.</li><li>Locate your home’s main water shutoff and make sure household members know where it is. Ask a plumber if it is unclear or inaccessible.</li></ul><p>Keep checks to accessible areas. Leave equipment covers, electrical work, combustion adjustments and work at height to qualified professionals.</p>'''),
('/seasonal-home-checklist/', 'Seasonal Home Maintenance Checklist | Delco & Main Line', 'Print a practical seasonal home checklist for heating, water, visible home repairs and planning your next local service visit.', 'A CHECKLIST YOU CAN ACTUALLY FINISH', 'Your next-season home checklist.', '''<p>For Delco, Chester County and Main Line homes: choose a few accessible checks, make a note of changes, and plan work before your busy season. Follow your equipment manuals. This is a planning list, not a service or safety inspection.</p><button class="btn outline" type="button" data-growth-print>Print this checklist</button><div class="growth-grid"><section><h2>Heating & comfort</h2><label class="growth-check"><input type="checkbox"> Record system model, fuel and last service date.</label><label class="growth-check"><input type="checkbox"> Check the manufacturer’s filter instructions and note the next change date.</label><label class="growth-check"><input type="checkbox"> Keep normal access to equipment and indoor vents unobstructed.</label><p><a href="/start/?intent=maintenance">Ask Middletown HVAC about maintenance →</a></p></section><section><h2>Water & moisture</h2><label class="growth-check"><input type="checkbox"> Look at accessible areas under sinks for visible moisture.</label><label class="growth-check"><input type="checkbox"> Note any change in hot-water performance.</label><label class="growth-check"><input type="checkbox"> Locate the main water shutoff; ask a plumber if you are unsure.</label><p><a href="/start/?intent=plumbing">Plan a plumbing conversation →</a></p></section><section><h2>Doors, windows & finishes</h2><label class="growth-check"><input type="checkbox"> Note sticking doors, drafts and visible water marks.</label><label class="growth-check"><input type="checkbox"> Photograph peeling finishes or damaged trim from ground level.</label><label class="growth-check"><input type="checkbox"> Write down the rooms and surfaces you want to improve.</label><p><a href="/start/?intent=windows">Plan window or surrounding repair work →</a></p></section><section><h2>Your home reference folder</h2><label class="growth-check"><input type="checkbox"> Review alarm testing and replacement instructions.</label><label class="growth-check"><input type="checkbox"> Gather warranties, prior invoices and project photos.</label><label class="growth-check"><input type="checkbox"> Pick one project and ask for a written scope.</label><p><a href="/project-kit/">Make a project preparation sheet →</a></p></section></div><p>Your checkmarks stay in this open page only. No account or email is needed. Printing may include your browser’s date and page address.</p>'''),
('/guides/repair-or-replace-hvac/', 'Repair or Replace Your HVAC? Questions Before You Decide', 'Prepare an HVAC repair-or-replacement conversation: diagnosis, repair scope, warranty, comfort issues and comparable written replacement proposals.', 'A CLEARER DECISION STARTS WITH BETTER QUESTIONS', 'Repair or replace? Get the whole picture.', '''<p>A large repair recommendation can feel like a deadline. Start with a documented diagnosis and comparable options. Equipment age alone does not settle the decision, and a simple online rule cannot inspect your home.</p><div class="growth-grid"><article><h2>1. Understand the finding.</h2><p>Ask what failed, how it was confirmed, what the repair includes and whether other findings change the recommendation. Ask the technician whether the equipment is safe to operate while you decide.</p></article><article><h2>2. Get the repair scope.</h2><p>Request the total written scope, parts and labor terms, what is excluded, and any applicable existing warranty. Ask what the proposed repair is expected to resolve and what remains uncertain.</p></article><article><h2>3. Define the replacement.</h2><p>Ask how sizing, distribution, controls, electrical or fuel work, permits and disposal will be handled. A replacement should address the home’s comfort problems, not simply swap a model number.</p></article><article><h2>4. Compare comparable options.</h2><p>Keep the repair and replacement proposals together. Look at scope, timing and written terms alongside price. Ask for the assumptions behind any claimed energy savings.</p></article></div><h2>Questions to bring to a second opinion.</h2><ul><li>Can you independently explain the diagnosis and options?</li><li>Does the recommendation address the rooms that are uncomfortable?</li><li>What work would each option leave for later?</li><li>What are the scheduling, payment and warranty terms?</li></ul><div class="growth-callout"><h2>Get another set of eyes on the recommendation.</h2><p>Middletown HVAC is listed for second-opinion inquiries. Confirm coverage, any diagnostic charge and appointment timing directly.</p><a class="btn primary" href="/start/?intent=secondopinion">Prepare a second-opinion request →</a> <a href="tel:+16105006416">Call 610-500-6416</a></div><p><a href="/compare/">Already have two proposals? Compare their scope →</a></p>'''),
('/project-budget/', 'Home Project Budget Calculator | Plan the Full Scope', 'Add your own written project costs and a planning allowance. See the arithmetic, keep notes private and prepare a clearer contractor conversation.', 'THE FULL PROJECT. FEWER SURPRISES.', 'Put the whole scope on one page.', '''<p>Use amounts from a written proposal or your own planning notes. This calculator adds your inputs; it does not estimate local prices, recommend a budget or provide a contractor quote. Enter zero only when a line is confirmed included or not applicable.</p><form id="growth-budget" class="growth-calculator"><label>Quoted work ($)<input name="work" type="number" min="0" max="10000000" step="0.01" inputmode="decimal" required></label><label>Other separately priced work ($)<input name="other" type="number" min="0" max="10000000" step="0.01" inputmode="decimal" required></label><label>Permits, delivery or disposal not already included ($)<input name="fees" type="number" min="0" max="10000000" step="0.01" inputmode="decimal" required></label><label>Your chosen planning allowance (%)<input name="allowance" type="number" min="0" max="100" step="0.1" inputmode="decimal" required></label><p>Check for overlapping costs before adding. Your allowance is an extra planning amount, not a prediction of overruns or a recommendation.</p><button class="btn primary" type="submit">Calculate my planning total</button><button class="btn outline" type="reset">Clear amounts</button><p id="growth-budget-result" role="status" aria-live="polite">Enter all four amounts to see your total.</p></form><noscript><p>Add the three dollar amounts. Multiply that subtotal by your allowance percentage divided by 100, then add the result to the subtotal.</p></noscript><p>Amounts stay in this open page. They are not saved or sent to Wazoozie. No sign-in is required.</p><h2>Before you use the total.</h2><ul><li>Ask which taxes, permits, delivery and cleanup are already included.</li><li>Identify any work another trade must price separately.</li><li>Confirm how concealed conditions and change orders will be handled.</li><li>Keep payment milestones and warranty terms with the written scope.</li></ul><a class="btn primary" href="/start/">Discuss a project with a local business →</a> <a href="/compare/">Compare two proposals →</a>'''),
('/share-wazoozie/', 'Share Wazoozie | Free Homeowner Tools & Local Businesses', 'Share free project tools and home tips with a neighbor, customer or community. Copy a public link or a short introduction to Wazoozie.', 'GOOD INFORMATION TRAVELS', 'A useful link for the next homeowner.', '''<p>Know someone planning work? Send a public tool they can use right away. These links contain no private project details. Copying prepares text for you to review and share yourself.</p><div class="growth-grid"><article><h2>For a neighbor.</h2><p>Free tools for the next home project: home tips, a seasonal checklist, a budget planner and named local businesses.</p><button class="btn outline" data-copy-share="home">Copy a short introduction</button></article><article><h2>For a community group.</h2><p>A printable checklist can make a useful resource in a neighborhood newsletter or community resource page.</p><button class="btn outline" data-copy-share="checklist">Copy the checklist link</button></article><article><h2>For a business website.</h2><p>Give customers a preparation sheet before their visit. Link to the public tool without implying a partnership or endorsement.</p><button class="btn outline" data-copy-share="tools">Copy the preparation-sheet link</button></article><article><h2>For local business owners.</h2><p>Apply for listing consideration or ask about clearly labeled sponsored visibility. Applying is free; placement and any paid terms are agreed separately.</p><a class="btn primary" href="/for-contractors/?interest=sponsored#business-application">Discuss sponsored visibility →</a></article></div><label class="growth-share-fallback">Review or manually copy the prepared text<textarea id="growth-share-text" rows="4" readonly></textarea></label><p id="growth-share-status" role="status" aria-live="polite"></p><p>Share where it is welcome and follow each community’s posting rules. Wazoozie does not send messages or publish posts when you use these buttons.</p>''')
]


def add(out, origin, pages):
    root = out.parent
    for name in ('growth.css', 'growth.js'):
        shutil.copy(root / 'assets' / name, out / 'assets' / name)
    for path, title, description, eyebrow, heading, body in PAGES:
        content = f'<div class="wrap growth-page"><div class="breadcrumb"><a href="/">Home</a><span>/</span><a href="/home-tips/">Home tips & tools</a></div><header class="growth-intro"><div class="eyebrow">{eyebrow}</div><h1>{html.escape(heading)}</h1></header>{body}<aside class="growth-next"><h2>A useful next step.</h2><p><a href="/home-tips/">Explore home tips</a> · <a href="/seasonal-home-checklist/">Print the checklist</a> · <a href="/project-budget/">Plan a budget</a> · <a href="/share-wazoozie/">Share with a neighbor</a></p></aside></div>'
        write_editorial_page(out, origin, pages, path, title, description, content)
        target = out / path.strip('/') / 'index.html'
        target.write_text(target.read_text().replace('</head>', '<link rel="stylesheet" href="/assets/growth.css"></head>').replace('</body>', '<script type="module" src="/assets/growth.js"></script></body>'))
    feature = '<section class="wrap growth-discovery" aria-labelledby="home-tips-heading"><div><span class="eyebrow">GOOD ADVICE TO KEEP. USEFUL TO SHARE.</span><h2 id="home-tips-heading">A little help before the first call.</h2><p>Home tips, a seasonal checklist and a budget planner. Free to use, with no account required.</p></div><div class="growth-discovery-links"><a href="/home-tips/">Home tips →</a><a href="/seasonal-home-checklist/">Seasonal checklist →</a><a href="/guides/repair-or-replace-hvac/">Repair or replace? →</a><a href="/project-budget/">Project budget planner →</a></div></section>'
    for target in out.rglob('*.html'):
        content = target.read_text()
        if target == out / 'index.html':
            content = content.replace('</main>', feature + '</main>', 1).replace('</head>', '<link rel="stylesheet" href="/assets/growth.css"></head>')
        if target == out / 'guides/index.html':
            content = content.replace('</main>', feature + '</main>', 1).replace('</head>', '<link rel="stylesheet" href="/assets/growth.css"></head>')
        content = content.replace('<strong>The useful details</strong>', '<strong>The useful details</strong><a href="/home-tips/">Home tips &amp; checklists</a><a href="/project-budget/">Project budget planner</a><a href="/share-wazoozie/">Share Wazoozie</a>')
        target.write_text(content)
